APP_st.name='APP';
APP_st.lat=36.2130;
APP_st.lon=-81.6920;
APP_st.alt=1076;
APP_st.env='con';
APP_st.footp='RB';
%%

APP_rd=read_betsy_2026('app_tsi_psap_clap_eco',APP_st.name); %[output:9060d0af]
names_rd=fieldnames(APP_rd);

APP_rd_nc=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Appalachian State University.nc', APP_st);
names_rd_nc=fieldnames(APP_rd_nc);
plotFigControl(APP_rd_nc,APP_st.name);
%%
datevec(APP_rd.Time(1)) %data since 2009 %[output:514e2ecf]
datevec(APP_rd.Time(end)) %2025 %[output:5c62887c]
prctile(APP_rd.U0_S11,[5 50 95]) % < 38% ok no need to compute dry trend %[output:0a3500c1]
prctile(APP_rd.U1_S11,[5 50 95]) %[output:2d06c44c]
plotFigControl(APP_rd,APP_st.name); %[output:73853975] %[output:174412e1] %[output:6a35fd48] %[output:638a1171] %[output:4ce0436d] %[output:1e1718ef] %[output:65a9bc0b] %[output:55450e7c]
% 2 size cut, ok
% sc: ok, max in summer, no negatives
% abs: 2 size cut, max in summer, no negatives
%very high seasonal cycle of abs ratio and abs exponent
%N:july/August 2011: too low: problem and rupture, often lower in summer

%problems:
%ratio B/R and G/R with higher max and min values since mid 2016: change PSAP --> CLAP
%should be due to the red wavelength change (660 to 653)

% ratio BbsG0/BsG1 and BbsG1/BsG1 and BbsG0/BsG0 rupture in the second part of september 2015?
% %and BbsG1/BsG0 very low in summer 2015
% SSA also show a rupture in september 2015 as well and the backscattering fraction and the exp BG
%%
% BP detection for scat coef and backscat

names_sc={'BsB0_S11', 'BsG0_S11', 'BsR0_S11','BsG1_S11'};
break_APP_scat_BP=change_point_analysis_Def(APP_rd,names_sc,0.05,'APP','scattering');
T_APP_scat_BP=make_table_breakpoints_def(break_APP_scat_BP);

names_bsc={'BbsB0_S11', 'BbsG0_S11', 'BbsR0_S11','BbsG1_S11'};
break_APP_bscat_BP=change_point_analysis_Def(APP_rd,names_bsc,0.05,'APP','Backscattering');
T_APP_bscat_BP=make_table_breakpoints_def(break_APP_bscat_BP);
%%
%Abs homogeneisation between PSAP and CLAP
% common period= 4.2.2012 - 15.1.2016
Pt=timerange('2012-02-01','2016-03-01');
ratio_med_h=nanmedian(APP_rd.BaG0_A11_psap(Pt)./APP_rd.BaG0_A12_clap(Pt)) % 1.0421 %[output:3af32782]
ratio_STN_h=nanstd(APP_rd.BaG0_A11_psap(Pt)./APP_rd.BaG0_A12_clap(Pt)) % 0.2887 %[output:1bf2e1f7]
ratio_mean_h=nanmean(APP_rd.BaG0_A11_psap(Pt)./APP_rd.BaG0_A12_clap(Pt)) % 1.0902 %[output:4534507f]
ratio_mean=nanmean(APP_rd.BaG0_A11_psap(Pt))/nanmean(APP_rd.BaG0_A12_clap(Pt)) % 1.0597 %[output:783a1690]
ratio_median=nanmedian(APP_rd.BaG0_A11_psap(Pt))/nanmedian(APP_rd.BaG0_A12_clap(Pt)) % 1.0893 %[output:6101957b]
figure; %[output:0788e32b]
plot(APP_rd.BaG0_A11_psap(Pt),APP_rd.BaG0_A12_clap(Pt),'.'); %[output:0788e32b]

% fit between both data: slope 0.8657x+0.1804
fit_test=robustfit(APP_rd.BaG0_A11_psap(Pt),APP_rd.BaG0_A12_clap(Pt)) % y coor=0.1130, slope=0.9029, 1/slope=1.1075 %[output:54d2849a]
%since the fit pass over (0,0), forcing him through 0,0 will lead to lower 1/slope

% --> use a cte=0.85 (middle between median and robust fit)
cte_psap_clap=1.05;
%%
% homogeneisation abs
P1=timerange('2009-01-01','2012-07-01');
P2=timerange('2012-07-01','2026-01-01');

% B
APP_rd.BaB0_S11S12=NaN(size(APP_rd.BaB0_A11_psap));
APP_rd.BaB0_S11S12(P1)=APP_rd.BaB0_A11_psap(P1).*cte_psap_clap;
APP_rd.BaB0_S11S12(P2)=APP_rd.BaB0_A12_clap(P2);

% G
APP_rd.BaG0_S11S12=NaN(size(APP_rd.BaG0_A11_psap));
APP_rd.BaG0_S11S12(P1)=APP_rd.BaG0_A11_psap(P1).*cte_psap_clap;
APP_rd.BaG0_S11S12(P2)=APP_rd.BaG0_A12_clap(P2);

% R
APP_rd.BaR0_S11S12=NaN(size(APP_rd.BaR0_A11_psap));
APP_rd.BaR0_S11S12(P1)=APP_rd.BaR0_A11_psap(P1).*cte_psap_clap;
APP_rd.BaR0_S11S12(P2)=APP_rd.BaR0_A12_clap(P2);
%%

names_abs={'BaB0_S11S12', 'BaB0_S11S12', 'BaB0_S11S12'};
break_APP_abs_BP=change_point_analysis_Def(APP_rd,names_abs,0.05,'APP','Absorption'); %[output:06f55808] %[output:94d2eb33] %[output:627fa8c7] %[output:5b55e61e]
T_APP_abs_BP=make_table_breakpoints_def(break_APP_abs_BP);
%[output:5e1d3d1f] %[output:3b5c3f50] %[output:26a6e6ca] %[output:7202b724] %[output:50824c9d] %[output:9c33f3a6] %[output:9222c68a] %[output:50c883e6]
%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
APP_cal=compute_exp_SSA(APP_rd,lambdaSC, lambdaAE);
plotFigControl_cal(APP_cal,APP_st.name);
%%
%Questions:
%problems:
%abs: ratio B/R and G/R with higher max and min values since mid 2016: change PSAP --> CLAP
%should be due to the red wavelength change (660 to 653)

%sc: are the very high points in November 2016 real or bad data ?
%sc:  ratio BbsG0/BsG1 and BbsG1/BsG1 and BbsG0/BsG0 rupture in the second part of september 2015?
% %and BbsG1/BsG0 very low in summer 2015
% SSA also show a rupture in september 2015 as well and the backscattering fraction and the exp BG
%%

APP_tr=APP_rd;
APP_tr.y=year(APP_tr.Time);
%eneleve une valeur de 2019
APP_tr=APP_tr(1:end-1,:);
% begin at the beginning of a year: 2010 (2017: 8y, 2018: 9y)
%end: 2018
P=timerange('2010-01-01','2019-01-01');
APP_tr=APP_tr(P,:);
% large RH change in october 2013: trend on U to do, but RH<50%, no need to trend on dry
names=fieldnames(APP_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_";"N";"Uu"]) | endsWith(names,'dry') | contains(names,'Q');
N=names(c);
for i=1:length(N)
    APP_tr.(N{i})=[];
end

%scat: 2-17.1.2015: scat + back red to invalidate
P2=timerange('2015-01-02','2015-01-17');
APP_tr.BsR0_S(P2)=NaN;
APP_tr.BsR1_S(P2)=NaN;
APP_tr.BbsR0_S(P2)=NaN;
APP_tr.BbsR1_S(P2)=NaN;
%scat: 15-21.9.2015: scat + backscat to invalidate, all wavelengths
P3=timerange('2015-09-15','2015-09-21');
APP_tr.BsB0_S(P3)=NaN;
APP_tr.BsB1_S(P3)=NaN;
APP_tr.BbsB0_S(P3)=NaN;
APP_tr.BbsB1_S(P3)=NaN;
APP_tr.BsG0_S(P3)=NaN;
APP_tr.BsG1_S(P3)=NaN;
APP_tr.BbsG0_S(P3)=NaN;
APP_tr.BbsG1_S(P3)=NaN;
APP_tr.BsR0_S(P3)=NaN;
APP_tr.BsR1_S(P3)=NaN;
APP_tr.BbsR0_S(P3)=NaN;
APP_tr.BbsR1_S(P3)=NaN;

APP_cal2=compute_exp_SSA(APP_tr,lambdaSC, lambdaAE);

%compute SSA with both G
APP_cal2.SSA0G=APP_tr.BsG0_S./(APP_tr.BsG0_S+APP_tr.BaG0_A);
APP_cal2.SSA1G=APP_tr.BsG1_S./(APP_tr.BsG1_S+APP_tr.BaG1_A);
APP_cal2.SSA011=[];
APP_cal2.SSA111=[];
APP_tr=outerjoin(APP_tr, APP_cal2);
% trend only on scat G
APP_tr.BsB0_S=[];
APP_tr.BsB1_S=[];
APP_tr.BsR0_S=[];
APP_tr.BsR1_S=[];
APP_tr.BbsB0_S=[];
APP_tr.BbsB1_S=[];
APP_tr.BbsR0_S=[];
APP_tr.BbsR1_S=[];

% trend on BG expS
APP_tr.expS_br0=[];
APP_tr.expS_gr0=[];
APP_tr.expS_br1=[];
APP_tr.expS_gr1=[];
%abs: 7.3.2016 PSAP to CLAP: ok for coef, BUT break point for ExpA at least with red: use BG et caution if positive trend
% trend only on abs G 
APP_tr.BaB0_A=[];
APP_tr.BaB1_A=[];
APP_tr.BaR0_A=[];
APP_tr.BaR1_A=[];

%trend only on ExpS bg
APP_tr.expA_br0=[];
APP_tr.expA_gr0=[];
APP_tr.expA_br1=[];
APP_tr.expA_gr1=[];
%%
%APP_result= all_trend_STN(APP_tr,APP_st); 

%compute the trend for 2018 == 9y of data
APP_result18= all_trend_STN(APP_tr,APP_st);
%%
APP_result_D=APP_result18;

